"""Lexer and recursive-descent parser for minisql. See SPEC.md.

``parse(sql)`` returns a ``minisql.ast.Query`` or raises ``QueryError``.

Design notes:

- Comparisons are non-associative: ``a = b = c`` (or ``a IS NULL = TRUE``)
  is a syntax error. Use parentheses to chain them.
- Unary minus is never constant-folded: ``-5`` is ``Unary("-", Literal(5))``.
- A double-quoted name is always a column/alias/table name, never a function
  name, so ``"lower"(x)`` is a syntax error.
- ``*`` as a function argument is only accepted as ``COUNT(*)``.
"""

from . import QueryError
from .ast import (
    Between,
    Binary,
    Call,
    Column,
    In,
    IsNull,
    Like,
    Literal,
    OrderItem,
    Query,
    SelectItem,
    Unary,
)

KEYWORDS = frozenset(
    """
    SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER ASC DESC LIMIT OFFSET
    AS AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE
    """.split()
)

# Token kinds
KEYWORD = "keyword"
IDENT = "identifier"
QIDENT = "quoted identifier"
NUMBER = "number"
STRING = "string"
OP = "operator"
EOF = "end of query"

_TWO_CHAR_OPS = ("<=", ">=", "<>", "!=", "||")
_ONE_CHAR_OPS = "=<>+-*/(),;"


class Token:
    __slots__ = ("kind", "value", "start", "end")

    def __init__(self, kind, value, start, end):
        self.kind = kind
        self.value = value  # keyword upper-cased; ident/qident name; parsed number/string
        self.start = start
        self.end = end

    def __repr__(self):
        return "Token(%s, %r, %d, %d)" % (self.kind, self.value, self.start, self.end)


def _is_ident_start(c):
    return c == "_" or ("a" <= c <= "z") or ("A" <= c <= "Z")


def _is_ident_char(c):
    return _is_ident_start(c) or ("0" <= c <= "9")


def _is_digit(c):
    return "0" <= c <= "9"


def tokenize(sql):
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if _is_ident_start(c):
            while i < n and _is_ident_char(sql[i]):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in KEYWORDS:
                tokens.append(Token(KEYWORD, upper, start, i))
            else:
                tokens.append(Token(IDENT, word, start, i))
            continue
        if _is_digit(c) or (c == "." and i + 1 < n and _is_digit(sql[i + 1])):
            while i < n and _is_digit(sql[i]):
                i += 1
            is_float = False
            if i < n and sql[i] == ".":
                is_float = True
                i += 1
                while i < n and _is_digit(sql[i]):
                    i += 1
            if i < n and (_is_ident_char(sql[i]) or sql[i] == "."):
                raise QueryError(
                    "invalid number %r at position %d" % (sql[start : i + 1], start)
                )
            text = sql[start:i]
            value = float(text) if is_float else int(text)
            tokens.append(Token(NUMBER, value, start, i))
            continue
        if c == "'" or c == '"':
            quote = c
            i += 1
            parts = []
            while True:
                j = sql.find(quote, i)
                if j < 0:
                    what = "string" if quote == "'" else "quoted name"
                    raise QueryError(
                        "unterminated %s starting at position %d" % (what, start)
                    )
                parts.append(sql[i:j])
                if j + 1 < n and sql[j + 1] == quote:
                    parts.append(quote)
                    i = j + 2
                else:
                    i = j + 1
                    break
            value = "".join(parts)
            if quote == "'":
                tokens.append(Token(STRING, value, start, i))
            else:
                if value == "":
                    raise QueryError("empty quoted name at position %d" % start)
                tokens.append(Token(QIDENT, value, start, i))
            continue
        two = sql[i : i + 2]
        if two in _TWO_CHAR_OPS:
            tokens.append(Token(OP, two, start, i + 2))
            i += 2
            continue
        if c in _ONE_CHAR_OPS:
            tokens.append(Token(OP, c, start, i + 1))
            i += 1
            continue
        raise QueryError("unexpected character %r at position %d" % (c, start))
    tokens.append(Token(EOF, None, n, n))
    return tokens


def _describe(tok):
    if tok.kind == EOF:
        return "end of query"
    if tok.kind == KEYWORD:
        return "keyword %s" % tok.value
    if tok.kind == STRING:
        return "string '%s'" % tok.value.replace("'", "''")
    if tok.kind == QIDENT:
        return 'name "%s"' % tok.value.replace('"', '""')
    if tok.kind == IDENT:
        return "name %s" % tok.value
    if tok.kind == NUMBER:
        return "number %r" % tok.value
    return "'%s'" % tok.value


_COMPARISON_OPS = ("=", "!=", "<>", "<", "<=", ">", ">=")


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = tokenize(sql)
        self.pos = 0

    # -- helpers -----------------------------------------------------------

    @property
    def tok(self):
        return self.tokens[self.pos]

    def peek(self, offset=1):
        idx = min(self.pos + offset, len(self.tokens) - 1)
        return self.tokens[idx]

    def advance(self):
        tok = self.tokens[self.pos]
        if tok.kind != EOF:
            self.pos += 1
        return tok

    def error(self, expected, tok=None):
        tok = tok or self.tok
        if tok.kind == EOF:
            where = "at end of query"
        else:
            where = "at position %d" % tok.start
        raise QueryError(
            "syntax error: expected %s but found %s %s"
            % (expected, _describe(tok), where)
        )

    def is_kw(self, *words):
        return self.tok.kind == KEYWORD and self.tok.value in words

    def is_op(self, *ops):
        return self.tok.kind == OP and self.tok.value in ops

    def accept_kw(self, word):
        if self.is_kw(word):
            return self.advance()
        return None

    def accept_op(self, op):
        if self.is_op(op):
            return self.advance()
        return None

    def expect_kw(self, word):
        if not self.is_kw(word):
            self.error(word)
        return self.advance()

    def expect_op(self, op):
        if not self.is_op(op):
            self.error("'%s'" % op)
        return self.advance()

    def expect_name(self, what="a name"):
        if self.tok.kind in (IDENT, QIDENT):
            return self.advance().value
        self.error(what)

    def expect_int(self, what):
        tok = self.tok
        if tok.kind == NUMBER and isinstance(tok.value, int):
            self.advance()
            return tok.value
        self.error("an integer after %s" % what)

    # -- query -------------------------------------------------------------

    def parse_query(self):
        self.expect_kw("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))
        if self.accept_op("*"):
            columns = None
        else:
            columns = [self.parse_select_item()]
            while self.accept_op(","):
                columns.append(self.parse_select_item())
        self.expect_kw("FROM")
        table = self.expect_name("a table name")
        query = Query(distinct=distinct, columns=columns, table=table)

        if self.accept_kw("WHERE"):
            query.where = self.parse_expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            query.group_by = [self.parse_expr()]
            while self.accept_op(","):
                query.group_by.append(self.parse_expr())
        if self.accept_kw("HAVING"):
            query.having = self.parse_expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            query.order_by = [self.parse_order_item()]
            while self.accept_op(","):
                query.order_by.append(self.parse_order_item())
        if self.accept_kw("LIMIT"):
            query.limit = self.expect_int("LIMIT")
            if self.accept_kw("OFFSET"):
                query.offset = self.expect_int("OFFSET")
        self.accept_op(";")
        if self.tok.kind != EOF:
            self.error("end of query")
        return query

    def parse_select_item(self):
        if self.is_op("*"):
            self.error("an expression (* can't be mixed with other columns)")
        start = self.tok.start
        expr = self.parse_expr()
        end = self.tokens[self.pos - 1].end
        text = self.sql[start:end]
        alias = None
        if self.accept_kw("AS"):
            alias = self.expect_name("an alias name after AS")
        elif self.tok.kind in (IDENT, QIDENT):
            alias = self.advance().value
        return SelectItem(expr=expr, alias=alias, text=text)

    def parse_order_item(self):
        expr = self.parse_expr()
        descending = False
        if self.accept_kw("DESC"):
            descending = True
        else:
            self.accept_kw("ASC")
        return OrderItem(expr=expr, descending=descending)

    # -- expressions -------------------------------------------------------

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left = self.parse_and()
        while self.accept_kw("OR"):
            left = Binary("OR", left, self.parse_and())
        return left

    def parse_and(self):
        left = self.parse_not()
        while self.accept_kw("AND"):
            left = Binary("AND", left, self.parse_not())
        return left

    def parse_not(self):
        if self.accept_kw("NOT"):
            return Unary("NOT", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self):
        left = self.parse_additive()
        tok = self.tok
        if tok.kind == OP and tok.value in _COMPARISON_OPS:
            self.advance()
            result = Binary(tok.value, left, self.parse_additive())
        elif self.accept_kw("IS"):
            negated = bool(self.accept_kw("NOT"))
            self.expect_kw("NULL")
            result = IsNull(left, negated)
        elif self.is_kw("NOT") and self.peek().kind == KEYWORD and self.peek().value in (
            "IN",
            "BETWEEN",
            "LIKE",
        ):
            self.advance()
            result = self.parse_postfix_predicate(left, True)
        elif self.is_kw("IN", "BETWEEN", "LIKE"):
            result = self.parse_postfix_predicate(left, False)
        else:
            return left
        # Comparisons don't chain.
        nxt = self.tok
        if (nxt.kind == OP and nxt.value in _COMPARISON_OPS) or (
            nxt.kind == KEYWORD and nxt.value in ("IS", "IN", "BETWEEN", "LIKE")
        ) or (
            nxt.kind == KEYWORD
            and nxt.value == "NOT"
            and self.peek().kind == KEYWORD
            and self.peek().value in ("IN", "BETWEEN", "LIKE")
        ):
            raise QueryError(
                "syntax error: comparisons can't be chained (found %s at position %d);"
                " use parentheses" % (_describe(nxt), nxt.start)
            )
        return result

    def parse_postfix_predicate(self, left, negated):
        if self.accept_kw("IN"):
            self.expect_op("(")
            items = [self.parse_expr()]
            while self.accept_op(","):
                items.append(self.parse_expr())
            self.expect_op(")")
            return In(left, items, negated)
        if self.accept_kw("BETWEEN"):
            low = self.parse_additive()
            self.expect_kw("AND")
            high = self.parse_additive()
            return Between(left, low, high, negated)
        self.expect_kw("LIKE")
        return Like(left, self.parse_additive(), negated)

    def parse_additive(self):
        left = self.parse_multiplicative()
        while self.is_op("+", "-", "||"):
            op = self.advance().value
            left = Binary(op, left, self.parse_multiplicative())
        return left

    def parse_multiplicative(self):
        left = self.parse_unary()
        while self.is_op("*", "/"):
            op = self.advance().value
            left = Binary(op, left, self.parse_unary())
        return left

    def parse_unary(self):
        if self.accept_op("-"):
            return Unary("-", self.parse_unary())
        return self.parse_primary()

    def parse_primary(self):
        tok = self.tok
        if tok.kind == NUMBER or tok.kind == STRING:
            self.advance()
            return Literal(tok.value)
        if tok.kind == KEYWORD:
            if tok.value == "NULL":
                self.advance()
                return Literal(None)
            if tok.value == "TRUE":
                self.advance()
                return Literal(True)
            if tok.value == "FALSE":
                self.advance()
                return Literal(False)
            self.error("an expression")
        if tok.kind == IDENT:
            self.advance()
            if self.is_op("("):
                return self.parse_call(tok.value.upper())
            return Column(tok.value)
        if tok.kind == QIDENT:
            self.advance()
            return Column(tok.value)
        if self.accept_op("("):
            expr = self.parse_expr()
            self.expect_op(")")
            return expr
        self.error("an expression")

    def parse_call(self, name):
        self.expect_op("(")
        if self.is_op("*"):
            if name != "COUNT":
                self.error("an argument (* is only allowed in COUNT(*))")
            self.advance()
            self.expect_op(")")
            return Call(name, [], star=True)
        args = []
        if not self.is_op(")"):
            args.append(self.parse_expr())
            while self.accept_op(","):
                args.append(self.parse_expr())
        self.expect_op(")")
        return Call(name, args)


def parse(sql):
    """Parse a SELECT query string into a ``minisql.ast.Query``."""
    if not isinstance(sql, str):
        raise QueryError("query must be a string")
    return _Parser(sql).parse_query()

